/*
 * test_capture.c - replay driver for the capture.c suite (ticket WP1-aT).
 *
 * Written from the SPEC (docs/agent/CONTRACTS.md C1.2/4/5/6/7/8 and the main-agent rulings),
 * never from the implementation. The driver only CALLS the API and prints what it observes;
 * oracle.py replays the identical scripted and random event sequences from the spec and
 * run_tests.py compares the text line by line, exactly.
 *
 * Events: I init, A arm, D disarm, R release, O overrun, P push, T push with trigger flag.
 * Directed scripts come from build/scripts.h (generated by oracle.py --emit-header); the random
 * episodes use xorshift32 and the same generator as oracle.py (Replay.episode).
 *
 * Host: ./test_capture_host SEED NEPISODES.  AVR: SEED / NEPISODES come from -DTEST_SEED/-DTEST_NEP.
 * The exit code is always 0; the verdict is the comparison done by run_tests.py.
 */
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include "sim16.h"
#include "capture.h"
#include "scripts.h"

#ifndef TEST_SEED
#define TEST_SEED 1u
#endif
#ifndef TEST_NEP
#define TEST_NEP 8u
#endif

#define L(x) ((long)(x))

static uint32_t g_rng;
static uint32_t g_n;                /* stream index of the next pushed sample */
static capture_state_t g_prev;      /* state reported after the previous event */
static uint32_t g_entries;          /* number of transitions into READY seen in random episodes */
static uint8_t  g_dump;             /* 0 none, 1 directed (full dumps), 2 random (every 8th entry), 3 sparse */
static uint32_t g_idx;              /* events executed in the current scenario */

/**
 * xorshift32 PRNG (13, 17, 5); mirrored bit for bit in oracle.py (class Rng).
 *
 * @return Next 32-bit pseudo-random value.
 */
static uint32_t rnd(void)
{
    uint32_t x = g_rng;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    g_rng = x;
    return x;
}

/**
 * Build the sample for stream index n; x and y carry the index, z mixes it. Mirrors oracle.sample.
 *
 * @param n Stream index.
 * @param s Receives the 3 axis values (all within [-2048, 2047]).
 * @return None.
 */
static void make_sample(uint32_t n, int16_t s[3])
{
    uint32_t z = ((n * 37u) ^ (n >> 5)) & 0xFFFu;
    s[0] = (int16_t)((int32_t)(n & 0xFFFu) - 2048);
    s[1] = (int16_t)((int32_t)((n >> 12) & 0xFFFu) - 2048);
    s[2] = (int16_t)((int32_t)z - 2048);
}

/**
 * Print the observable state after an event, plus the locked buffer while READY.
 * Line formats are documented in oracle.py (Replay.ev).
 *
 * @param op  Event letter that was just executed.
 * @param ret Return value of the call (0 or 1) for ops D R O P T, -1 (printed "-") for I and A.
 * @return None.
 */
static void report(char op, int16_t ret)
{
    capture_stats_t cs;
    capture_state_t st = capture_state();
    int16_t (*b)[3];
    uint32_t sum = 0u;
    uint8_t i;
    bool entry;

    capture_stats(&cs);
    g_idx++;
    if (g_dump == 3u && !((g_idx % 4096u) == 0u || cs.overruns <= 1u || cs.overruns >= 65534u ||
                          cs.early_triggers <= 1u || cs.early_triggers >= 65534u)) {
        g_prev = st;
        return;
    }
    printf("E %c %c %d %ld %ld %ld %ld\n", op, (ret < 0) ? '-' : (ret ? '1' : '0'), (int)st,
           L(capture_ring_count()), L(cs.overruns), L(cs.windows), L(cs.early_triggers));
    if (st == CAPTURE_READY) {
        entry = (g_prev != CAPTURE_READY);
        if (entry) {
            g_entries++;
        }
        b = capture_buffer();
        for (i = 0u; i < CAPTURE_LEN; i++) {
            sum = sum * 31u + (uint32_t)(uint16_t)b[i][0];
            sum = sum * 31u + (uint32_t)(uint16_t)b[i][1];
            sum = sum * 31u + (uint32_t)(uint16_t)b[i][2];
        }
        printf("W %lu\n", (unsigned long)sum);
        if (entry || op != 'P') {
            printf("F %d,%d,%d %d,%d,%d %d,%d,%d\n", (int)b[0][0], (int)b[0][1], (int)b[0][2],
                   (int)b[1][0], (int)b[1][1], (int)b[1][2], (int)b[2][0], (int)b[2][1], (int)b[2][2]);
            printf("L %d,%d,%d %d,%d,%d %d,%d,%d\n", (int)b[147][0], (int)b[147][1], (int)b[147][2],
                   (int)b[148][0], (int)b[148][1], (int)b[148][2], (int)b[149][0], (int)b[149][1],
                   (int)b[149][2]);
        }
        if ((g_dump == 1u && (entry || op != 'P')) ||
            (g_dump == 2u && entry && (g_entries % 8u) == 0u)) {
            for (i = 0u; i < CAPTURE_LEN; i++) {
                printf("B %d %d,%d,%d\n", (int)i, (int)b[i][0], (int)b[i][1], (int)b[i][2]);
            }
        }
    }
    g_prev = st;
}

/**
 * Execute one event on the API and report it.
 *
 * @param op One of I A D R O P T.
 * @return None.
 */
static void ev(char op)
{
    int16_t s[3];
    int16_t ret = -1;

    switch (op) {
    case 'I':
        capture_init();
        break;
    case 'A':
        capture_arm();
        break;
    case 'D':
        ret = capture_disarm() ? 1 : 0;
        break;
    case 'R':
        ret = capture_release() ? 1 : 0;
        break;
    case 'O':
        ret = capture_overrun() ? 1 : 0;
        break;
    default:
        make_sample(g_n, s);
        g_n++;
        ret = capture_push(s, op == 'T') ? 1 : 0;
        break;
    }
    report(op, ret);
}

/**
 * Start a scenario: print its header and reset the per-scenario bookkeeping.
 *
 * @param name Scenario name.
 * @param dump Dump mode (see g_dump).
 * @return None.
 */
static void begin(const char *name, uint8_t dump)
{
    printf("S %s\n", name);
    g_dump = dump;
    g_prev = CAPTURE_IDLE;
    g_idx = 0u;
}

/**
 * Parse an optional decimal repeat count.
 *
 * @param pp In/out: points at the first possible digit, advanced past the digits.
 * @return The count; 1 when there are no digits.
 */
static uint32_t read_count(const char **pp)
{
    const char *p = *pp;
    uint32_t cnt = 0u;
    bool any = false;

    while (*p >= '0' && *p <= '9') {
        cnt = cnt * 10u + (uint32_t)(*p - '0');
        any = true;
        p++;
    }
    *pp = p;
    return any ? cnt : 1u;
}

/**
 * Execute the ops in [p, end): op letters with optional repeat counts, or one level of "(ops)N".
 *
 * @param p   First character.
 * @param end One past the last character.
 * @return None.
 */
static void exec_seq(const char *p, const char *end)
{
    const char *q;
    const char *body;
    char op;
    uint32_t cnt, k;

    while (p < end) {
        if (*p == ' ') {
            p++;
        } else if (*p == '(') {
            body = p + 1;
            q = body;
            while (*q != ')') {
                q++;
            }
            p = q + 1;
            cnt = read_count(&p);
            for (k = 0u; k < cnt; k++) {
                exec_seq(body, q);
            }
        } else {
            op = *p++;
            cnt = read_count(&p);
            for (k = 0u; k < cnt; k++) {
                ev(op);
            }
        }
    }
}

/**
 * Run one directed script (grammar in oracle.py).
 *
 * @param name   Scenario name.
 * @param script Script text.
 * @param dump   Dump mode.
 * @return None.
 */
static void run_script(const char *name, const char *script, uint8_t dump)
{
    const char *e = script;

    begin(name, dump);
    g_n = 0u;
    while (*e != '\0') {
        e++;
    }
    exec_seq(script, e);
}

/**
 * Run one random episode: init, then 150..400 random events, optionally ending in a disarm.
 * Mirrors Replay.episode in oracle.py (same PRNG call order). Idle pushes (plain and with the
 * trigger flag) and mid-episode disarms are generated.
 *
 * @param k Episode number.
 * @return None.
 */
static void run_random(uint32_t k)
{
    static const uint16_t TRIG_TAB[4] = {10u, 30u, 100u, 400u};
    static const uint16_t OVR_TAB[4] = {0u, 2u, 6u, 20u};
    static const uint16_t REL_TAB[3] = {10u, 30u, 80u};
    char nm[16];
    uint16_t ptrig, povr, prel, x;
    uint32_t nev, i;
    bool idle;

    snprintf(nm, sizeof nm, "rand%lu", (unsigned long)k);
    begin(nm, 2u);
    ptrig = TRIG_TAB[rnd() % 4u];
    povr = OVR_TAB[rnd() % 4u];
    prel = REL_TAB[rnd() % 3u];
    nev = 150u + rnd() % 251u;
    ev('I');
    idle = true;
    for (i = 0u; i < nev; i++) {
        x = (uint16_t)(rnd() % 1000u);
        if (idle) {
            if (x < 400u) {
                ev('A');
                idle = false;
            } else if (x < 500u) {
                ev('O');
            } else if (x < 600u) {
                ev('R');
            } else if (x < 650u) {
                ev('I');
            } else if (x < 900u) {
                ev('P');
            } else {
                ev('T');
            }
        } else if (x < povr) {
            ev('O');
        } else if (x < (uint16_t)(povr + prel)) {
            ev('R');
        } else if (x < (uint16_t)(povr + prel + 5u)) {
            ev('A');
        } else if (x < (uint16_t)(povr + prel + 8u)) {
            ev('I');
            idle = true;
        } else if (x < (uint16_t)(povr + prel + 12u)) {
            ev('D');
            idle = true;
        } else if (x < (uint16_t)(povr + prel + 12u + ptrig)) {
            ev('T');
        } else {
            ev('P');
        }
    }
    if (rnd() % 4u == 0u) {
        ev('D');
    }
}

/**
 * Entry point: directed scripts, then NEP random episodes.
 *
 * @param argc Argument count (host build only).
 * @param argv Host: SEED NEPISODES.
 * @return 0 always; the verdict is the runner's comparison with the oracle.
 */
int main(int argc, char **argv)
{
    uint32_t seed = TEST_SEED;
    uint32_t nep = TEST_NEP;
    uint32_t k;

#ifndef __AVR__
    if (argc > 1) {
        seed = (uint32_t)strtoul(argv[1], NULL, 0);
    }
    if (argc > 2) {
        nep = (uint32_t)strtoul(argv[2], NULL, 0);
    }
#else
    (void)argc;
    (void)argv;
#endif
    sim16_init();
    for (k = 0u; k < N_DIRECTED; k++) {
        run_script(DIRECTED[k].name, DIRECTED[k].script, DIRECTED[k].dump);
    }
    g_rng = seed ^ 0x9E3779B9u;
    if (g_rng == 0u) {
        g_rng = 1u;
    }
    g_n = 0u;
    g_entries = 0u;
    for (k = 0u; k < nep; k++) {
        run_random(k);
    }
    sim16_exit(0);
    return 0;
}
